def levelOrder(root: Optional[TreeNode]) -> List[List[int]]:
    if not root:
        return []
    levels = []

    def get_height(node):
        if not node:
            return 0
        return 1 + max(get_height(node.left), get_height(node.right))

    def get_nodes_at_level(node, current_level, target_level, acc):
        if not node:
            return
        if current_level == target_level:
            acc.append(node.val)
            return
        get_nodes_at_level(node.left, current_level + 1, target_level, acc)
        get_nodes_at_level(node.right, current_level + 1, target_level, acc)

    h = get_height(root)
    for i in range(1, h + 1):
        level_vals = []
        get_nodes_at_level(root, 1, i, level_vals)
        levels.append(level_vals)
    return levels

